import Foundation
import FUMStructuringOperatorMemory
import Darwin

@main
struct КлиентПрямогоШага {
  private static let пределВывода = 16384

  private enum Отказ: String, Error {
    case аргументы = "число-аргументов"
    case размерФайла = "предел-файла"
    case кодировка = "строгий-UTF8"
    case объект = "ожидался-объект-JSON"
    case размерРезультата = "предел-результата"
    case типРезультата = "результат-не-текст"
    case приёмник = "контракт-приёмника"
    case данныеПланировщика = "контракт-входа-планировщика"
    case планировщик = "контракт-планировщика"
    case размерВывода = "предел-вывода"
  }

  private struct КонтрольПриёмника: Decodable {
    let схема: String
    let решение: String
    let новыйКандидат: Bool
    let эффектыРазрешены: Bool
  }

  private struct КонтрольПланировщика: Decodable {
    struct Решение: Decodable { let ресурсовВыделено: Int }
    let вид: String
    let версия: Int
    let привязкаПринята: Bool
    let решение: Решение
  }

  private static func прочитать(_ путь: String, предел: Int) throws -> Data {
    let файл = try FileHandle(forReadingFrom: URL(fileURLWithPath: путь))
    defer { try? файл.close() }
    var данные = Data()
    while данные.count <= предел {
      let остаток = предел + 1 - данные.count
      guard let часть = try файл.read(upToCount: остаток), !часть.isEmpty else { break }
      данные.append(часть)
    }
    guard данные.count <= предел else { throw Отказ.размерФайла }
    return данные
  }

  private static func объект(_ данные: Data, предел: Int) throws -> [String: Any] {
    guard данные.count <= предел else { throw Отказ.размерРезультата }
    guard let значение = try JSONSerialization.jsonObject(with: данные) as? [String: Any] else {
      throw Отказ.объект
    }
    return значение
  }

  private static func результат(_ наблюдение: НаблюдениеОператора) throws -> (Data, [String: Any]) {
    guard case .текст(let строка) = наблюдение.результат else { throw Отказ.типРезультата }
    let данные = Data(строка.utf8)
    return (данные, try объект(данные, предел: пределВывода))
  }

  private static func ошибка(_ код: String, библиотека: String? = nil) -> Data {
    var поля: [String: Any] = [
      "схема": "fum.ошибка-прямой-композиции.1", "код": код,
      "эффектыРазрешены": false
    ]
    if let библиотека {
      поля["кодБиблиотеки"] = библиотека.utf8.count <= 128 ? библиотека : "код-вне-предела"
    }
    if var данные = try? JSONSerialization.data(withJSONObject: поля, options: [.sortedKeys, .withoutEscapingSlashes]), данные.count + 1 <= 1024 {
      данные.append(10)
      return данные
    }
    return Data("{\"схема\":\"fum.ошибка-прямой-композиции.1\",\"код\":\"ошибка-сериализации\",\"эффектыРазрешены\":false}\n".utf8)
  }

  private static func завершить(_ данные: Data) -> Never {
    try? FileHandle.standardError.write(contentsOf: данные)
    exit(1)
  }

  static func main() {
    do {
      let аргументы = CommandLine.arguments
      guard аргументы.count == 4 else { throw Отказ.аргументы }
      let данныеПриёмника = try прочитать(аргументы[1], предел: 65536)
      let данныеПланировщика = try прочитать(аргументы[2], предел: 65536)
      let данныеВхода = try прочитать(аргументы[3], предел: 262144)
      guard let строкаВхода = String(data: данныеВхода, encoding: .utf8) else { throw Отказ.кодировка }
      _ = try объект(данныеВхода, предел: 262144)
      let приёмник = try ОпределениеОператора.разобрать(данныеПриёмника)
      let планировщик = try ОпределениеОператора.разобрать(данныеПланировщика)
      let наблюдениеПриёмника = try AutomationExecutor.выполнить(
        приёмник, вход: .текст(строкаВхода), пределы: ПределыИсполнения(), профиль: nil
      )
      let (байтыПриёмника, результатПриёмника) = try результат(наблюдениеПриёмника)
      let контроль = try JSONDecoder().decode(КонтрольПриёмника.self, from: байтыПриёмника)
      guard контроль.схема == "fum.результат-приёма-геометрии.1", !контроль.эффектыРазрешены else {
        throw Отказ.приёмник
      }
      var итогПланировщика: [String: Any] = ["состояние": "отсутствует"]
      if результатПриёмника.keys.contains("входПланировщика") {
        guard контроль.новыйКандидат, контроль.решение == "кандидат",
              let данныеПланировщика = результатПриёмника["входПланировщика"] as? [String: Any] else { throw Отказ.данныеПланировщика }
        let байтыВходаПланировщика = try JSONSerialization.data(withJSONObject: данныеПланировщика, options: [.sortedKeys, .withoutEscapingSlashes])
        guard байтыВходаПланировщика.count <= 262144 else { throw Отказ.размерРезультата }
        guard let строкаВходаПланировщика = String(data: байтыВходаПланировщика, encoding: .utf8) else { throw Отказ.кодировка }
        let наблюдениеПланировщика = try AutomationExecutor.выполнить(
          планировщик, вход: .текст(строкаВходаПланировщика), пределы: ПределыИсполнения(), профиль: nil
        )
        let (байтыПлана, результатПлана) = try результат(наблюдениеПланировщика)
        let проверкаПлана = try JSONDecoder().decode(КонтрольПланировщика.self, from: байтыПлана)
        guard проверкаПлана.вид == "допуск-кадра-окна", проверкаПлана.версия == 1,
              проверкаПлана.решение.ресурсовВыделено == 0 else { throw Отказ.планировщик }
        итогПланировщика = [
          "состояние": "выполнен", "результат": результатПлана,
          "хэшОпределения": наблюдениеПланировщика.хэшОпределения,
          "хэшВхода": наблюдениеПланировщика.хэшИсходныхБайтов
        ]
      } else {
        guard !контроль.новыйКандидат,
              ["состояние", "закрыто", "игнорировать", "диагностика"].contains(контроль.решение) else {
          throw Отказ.данныеПланировщика
        }
      }
      let итог: [String: Any] = [
        "схема": "fum.исход-прямой-композиции-геометрии.1", "версия": 1,
        "приёмник": [
          "результат": результатПриёмника,
          "хэшОпределения": наблюдениеПриёмника.хэшОпределения,
          "хэшВхода": наблюдениеПриёмника.хэшИсходныхБайтов
        ],
        "планировщик": итогПланировщика, "эффектыРазрешены": false
      ]
      var вывод = try JSONSerialization.data(withJSONObject: итог, options: [.sortedKeys, .withoutEscapingSlashes])
      guard вывод.count + 1 <= пределВывода else { throw Отказ.размерВывода }
      вывод.append(10)
      try FileHandle.standardOutput.write(contentsOf: вывод)
    } catch let отказ as Отказ {
      завершить(ошибка(отказ.rawValue))
    } catch let отказ as ОшибкаИсполнения {
      завершить(ошибка("ошибка-библиотеки", библиотека: отказ.код))
    } catch {
      завершить(ошибка("ввод-вывод-или-JSON"))
    }
  }
}
